import{_ as a,H as i,f as l,i as n}from"./chunks/framework.BGnj2dTC.js";const k=JSON.parse('{"title":"如何用 skill-creator 创建自己的 Skill","description":"","frontmatter":{},"headers":[],"relativePath":"note/ai/agent/output/如何用 skill-creator 创建自己的 Skill.md","filePath":"note/ai/agent/output/如何用 skill-creator 创建自己的 Skill.md"}'),e={name:"note/ai/agent/output/如何用 skill-creator 创建自己的 Skill.md"};function p(t,s,d,c,o,h){return i(),l("div",null,[...s[0]||(s[0]=[n(`<h1 id="如何用-skill-creator-创建自己的-skill" tabindex="-1">如何用 skill-creator 创建自己的 Skill <a class="header-anchor" href="#如何用-skill-creator-创建自己的-skill" aria-label="Permalink to &quot;如何用 skill-creator 创建自己的 Skill&quot;">​</a></h1><blockquote><p>这是 Skill 系列的第三篇。本文重点不是手写一个 <code>SKILL.md</code>，而是讲如何让 Codex 使用 <code>skill-creator</code> 自动创建或更新 Skill。</p></blockquote><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><p>创建 Skill 最省事的方式，不是自己手写目录，也不是自己去找初始化命令，而是直接让 Codex 使用 <code>skill-creator</code>。</p><p>你要做的是把需求说清楚：</p><ul><li>Skill 名称或大致用途。</li><li>什么时候触发。</li><li>需要完成哪些任务。</li><li>期望输出什么。</li><li>是否需要脚本、参考资料或模板。</li><li>安装到哪里，比如全局 <code>~/.codex/skills</code>，还是当前项目目录。</li></ul><p><code>skill-creator</code> 会负责把这些信息整理成一个可复用的 Skill。</p><h2 id="什么时候应该创建自己的-skill" tabindex="-1">什么时候应该创建自己的 Skill？ <a class="header-anchor" href="#什么时候应该创建自己的-skill" aria-label="Permalink to &quot;什么时候应该创建自己的 Skill？&quot;">​</a></h2><p>如果一个任务只做一次，不一定要写 Skill。</p><p>但如果你发现自己反复对 AI 说同样的话，就应该考虑沉淀成 Skill。</p><p>典型信号包括：</p><ul><li>你经常复制同一段 prompt。</li><li>你经常纠正 AI 的同一种错误。</li><li>你希望某类输出保持固定格式。</li><li>你有一套自己的审美、流程或判断标准。</li><li>你希望换工具后仍能复用这套经验。</li></ul><p>比如写文章这件事，如果你每次都要提醒：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>不要写得太像 AI。</span></span>
<span class="line"><span>开头别废话。</span></span>
<span class="line"><span>先给结论。</span></span>
<span class="line"><span>每段短一点。</span></span>
<span class="line"><span>保留关键判断。</span></span>
<span class="line"><span>不要乱用形容词。</span></span></code></pre></div><p>那就应该做一个写作 Skill。</p><h2 id="如何给-skill-creator-下任务" tabindex="-1">如何给 skill-creator 下任务？ <a class="header-anchor" href="#如何给-skill-creator-下任务" aria-label="Permalink to &quot;如何给 skill-creator 下任务？&quot;">​</a></h2><p>最简单的说法是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 skill-creator，帮我创建一个 weekly-report skill。</span></span>
<span class="line"><span>它用于把零散工作记录整理成周报，需要包含信息归类、风险提炼、下周计划和输出格式。</span></span>
<span class="line"><span>放到全局 Codex skills 目录。</span></span></code></pre></div><p>如果任务更复杂，可以把目标、触发条件、能力、资源和位置写清楚：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 skill-creator 创建一个 contract-review skill。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标：</span></span>
<span class="line"><span>当用户要求审阅合同、识别风险条款、总结修改建议时触发。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>能力：</span></span>
<span class="line"><span>1. 提取合同主体、金额、期限、付款和违约责任。</span></span>
<span class="line"><span>2. 标记高风险条款和模糊表述。</span></span>
<span class="line"><span>3. 给出修改建议和需要人工确认的问题。</span></span>
<span class="line"><span>4. 输出一份结构化审阅摘要。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>资源：</span></span>
<span class="line"><span>需要 references/clause-checklist.md 记录常见条款检查清单。</span></span>
<span class="line"><span>需要 assets/ 存放审阅报告模板。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>位置：</span></span>
<span class="line"><span>安装到全局 Codex skills 目录。</span></span></code></pre></div><p>这类请求比“帮我创建一个合同 Skill”稳定得多，因为它给了 <code>skill-creator</code> 足够的边界。</p><h2 id="skill-creator-会做什么" tabindex="-1">skill-creator 会做什么？ <a class="header-anchor" href="#skill-creator-会做什么" aria-label="Permalink to &quot;skill-creator 会做什么？&quot;">​</a></h2><p><code>skill-creator</code> 不是只生成一个空文件夹。它会把创建 Skill 拆成一套流程：</p><ol><li>理解这个 Skill 要解决什么问题。</li><li>追问或整理几个真实触发例子。</li><li>规划是否需要 <code>scripts/</code>、<code>references/</code>、<code>assets/</code>。</li><li>创建 Skill 目录和 <code>SKILL.md</code>。</li><li>写好 <code>name</code>、<code>description</code> 和正文流程。</li><li>必要时补充资源文件。</li><li>校验 Skill 结构和触发描述。</li><li>根据真实任务继续迭代。</li></ol><p>这种方式的好处是，<code>skill-creator</code> 会站在“另一个 Codex 将来怎么使用这个 Skill”的角度来设计，而不是只帮你写一份说明文档。</p><p>底层可能仍然会创建目录、生成 <code>SKILL.md</code>、补充资源文件、做校验，但这些是执行细节，不需要用户自己手动操作。</p><h2 id="第-1-步-用具体例子定义-skill" tabindex="-1">第 1 步：用具体例子定义 Skill <a class="header-anchor" href="#第-1-步-用具体例子定义-skill" aria-label="Permalink to &quot;第 1 步：用具体例子定义 Skill&quot;">​</a></h2><p>不要一开始就写一个“大而全的万能 Skill”。</p><p>适合做成 Skill 的任务，通常有几个特点：</p><ul><li>你经常做。</li><li>你已经形成了一套判断标准。</li><li>每次做都需要类似流程。</li><li>任务结果可以被检查。</li></ul><p>比如：</p><ul><li>写工作周报。</li><li>审阅合同。</li><li>整理会议纪要。</li><li>审校文章。</li><li>生成产品需求文档。</li><li>把 Mermaid 图转换成图片。</li></ul><p>更好的做法，是先列出 3 到 5 个真实使用例子。</p><p>比如你要创建一个“合同审阅 Skill”，可以先写：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户说：帮我看一下这份合同有没有明显风险。</span></span>
<span class="line"><span>用户说：把这份采购合同里的付款、验收和违约条款整理出来。</span></span>
<span class="line"><span>用户说：给我一份合同审阅摘要，并列出需要法务确认的问题。</span></span></code></pre></div><p>然后分析这些例子：</p><ul><li>用户通常会提供什么输入？合同文本、合同类型、关注重点。</li><li>AI 应该产出什么？风险摘要、条款清单、修改建议、待确认问题。</li><li>哪些规则是稳定的？先提取关键条款，再判断风险，最后给修改建议。</li><li>哪些资源可以复用？条款检查清单、审阅报告模板、常见风险说明。</li></ul><p>这一步的目标，是把 Skill 的边界从“我想要一个合同 Skill”变成“这个 Skill 负责哪些输入、流程和输出”。</p><h2 id="第-2-步-给-skill-正确命名" tabindex="-1">第 2 步：给 Skill 正确命名 <a class="header-anchor" href="#第-2-步-给-skill-正确命名" aria-label="Permalink to &quot;第 2 步：给 Skill 正确命名&quot;">​</a></h2><p>Skill 名称不是随便起的。</p><p>建议遵守这些规则：</p><ul><li>只使用小写字母、数字和连字符。</li><li>文件夹名和 Skill name 保持一致。</li><li>控制在 64 个字符以内。</li><li>尽量短，但要说明动作。</li><li>需要时用工具或平台做命名空间。</li></ul><p>比如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weekly-report</span></span>
<span class="line"><span>contract-review</span></span>
<span class="line"><span>markdown-mermaid-to-images</span></span>
<span class="line"><span>gh-address-comments</span></span>
<span class="line"><span>linear-address-issue</span></span></code></pre></div><p>不建议这样命名：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>My Awesome Skill</span></span>
<span class="line"><span>super-ai-helper</span></span>
<span class="line"><span>do-everything</span></span>
<span class="line"><span>写文章神器</span></span></code></pre></div><p>命名越具体，越不容易和其他 Skill 冲突。</p><h2 id="第-3-步-写好-description" tabindex="-1">第 3 步：写好 description <a class="header-anchor" href="#第-3-步-写好-description" aria-label="Permalink to &quot;第 3 步：写好 description&quot;">​</a></h2><p><code>description</code> 不是给人看的简介，而是给 AI 用来判断“什么时候该加载”的触发条件。</p><p>一个好的 description 应该包含三类信息：</p><ul><li>能力：这个 Skill 能做什么。</li><li>场景：什么时候使用。</li><li>触发词：用户说哪些话时应该想到它。</li></ul><p>示例：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">contract-review</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;审阅合同并提取风险。适用于合同审阅、条款检查、风险识别、修改建议。当用户要求检查合同、总结合同风险或整理关键条款时使用。&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span></code></pre></div><p>不要只写：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;处理合同&quot;</span></span></code></pre></div><p>因为处理合同的场景太多了：审阅、翻译、摘要、归档、比对版本都可能匹配。边界太宽，冲突就会变多。</p><p>还有一个容易忽略的点：什么时候使用，最好写在 <code>description</code> 里，而不是只写在正文里。</p><p>原因很简单：AI 只有在 Skill 触发后才会读取正文。如果触发条件只写在正文里，模型可能根本不会加载这个 Skill。</p><h2 id="第-4-步-规划资源目录" tabindex="-1">第 4 步：规划资源目录 <a class="header-anchor" href="#第-4-步-规划资源目录" aria-label="Permalink to &quot;第 4 步：规划资源目录&quot;">​</a></h2><p>Skill 不一定只有说明文字。它可以包含：</p><ul><li><code>scripts/</code>：重复、脆弱、需要稳定执行的脚本。</li><li><code>references/</code>：长文档、规范、API、业务知识。</li><li><code>assets/</code>：模板、图片、字体、示例项目、PPT 模板。</li><li><code>agents/openai.yaml</code>：面向 UI 展示的名称、简介和默认提示。</li></ul><p>判断方法很简单：看真实例子里有哪些事情会反复出现。</p><p>如果每次都要重写同一段代码，就放进 <code>scripts/</code>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pdf-editor/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>└── scripts/</span></span>
<span class="line"><span>    └── rotate_pdf.py</span></span></code></pre></div><p>如果每次都要查同一套表结构、接口文档或公司规范，就放进 <code>references/</code>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bigquery-analytics/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>└── references/</span></span>
<span class="line"><span>    ├── finance.md</span></span>
<span class="line"><span>    ├── sales.md</span></span>
<span class="line"><span>    └── product.md</span></span></code></pre></div><p>如果每次都要用同一套模板或素材，就放进 <code>assets/</code>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>frontend-webapp-builder/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>└── assets/</span></span>
<span class="line"><span>    └── starter-template/</span></span></code></pre></div><p>很多低质量 Skill 的问题，是把所有东西都塞进 <code>SKILL.md</code>，最后文件臃肿、加载成本高、重点不清楚。</p><h2 id="第-5-步-把流程写成可执行步骤" tabindex="-1">第 5 步：把流程写成可执行步骤 <a class="header-anchor" href="#第-5-步-把流程写成可执行步骤" aria-label="Permalink to &quot;第 5 步：把流程写成可执行步骤&quot;">​</a></h2><p>Skill 不是理念宣言，而是操作手册。</p><p>不要只写：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你要写得专业、自然、有深度。</span></span></code></pre></div><p>这类要求太抽象，模型知道方向，但不知道怎么落地。</p><p>更好的写法是：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 工作流程</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 先判断文章类型：教程、解释型文章、架构文章、对比文章或复盘文章。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 根据文章类型选择对应结构。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 开头先给 TL;DR，不要写泛泛背景。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 每个关键判断必须解释原因。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">5.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 涉及代码时，代码块必须标注语言，并保证示例可以独立理解。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">6.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 结尾写清楚适用场景和限制。</span></span></code></pre></div><p>写流程时，还要控制自由度。</p><table tabindex="0"><thead><tr><th>自由度</th><th>适合场景</th><th>写法</th></tr></thead><tbody><tr><td>高自由度</td><td>写作、方案、设计评审</td><td>规则、原则、判断标准</td></tr><tr><td>中自由度</td><td>有固定模式但允许变化</td><td>伪代码、流程图、参数化步骤</td></tr><tr><td>低自由度</td><td>容易出错、必须稳定执行</td><td>脚本、固定命令、少量参数</td></tr></tbody></table><p>比如“写分析文章”可以保留较高自由度，因为不同主题需要不同表达。</p><p>但“把 Mermaid 图渲染成图片”就应该降低自由度，最好提供脚本和固定命令，而不是让 AI 每次自己想办法。</p><h2 id="第-6-步-写质量标准和反例" tabindex="-1">第 6 步：写质量标准和反例 <a class="header-anchor" href="#第-6-步-写质量标准和反例" aria-label="Permalink to &quot;第 6 步：写质量标准和反例&quot;">​</a></h2><p>好的 Skill 不只告诉 AI “应该做什么”，还要告诉它“不要做什么”。</p><p>比如文章整理 Skill 里可以写：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 避免</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要使用“在当今快速发展的时代”这类空泛开头。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要把核心结论埋在三段背景之后。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要写无法运行的代码片段。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要假装方案没有取舍。</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要使用营销话术替代具体解释。</span></span></code></pre></div><p>反例很有用。它能把“我不喜欢这种感觉”翻译成模型可以执行的约束。</p><h2 id="第-7-步-按渐进加载拆分内容" tabindex="-1">第 7 步：按渐进加载拆分内容 <a class="header-anchor" href="#第-7-步-按渐进加载拆分内容" aria-label="Permalink to &quot;第 7 步：按渐进加载拆分内容&quot;">​</a></h2><p>当 Skill 变大以后，不要继续往 <code>SKILL.md</code> 里塞内容。</p><p>渐进加载的核心原则是：</p><ol><li>元信息始终短小，用来触发。</li><li><code>SKILL.md</code> 只放核心流程，最好不要超过几百行。</li><li>长资料放到 <code>references/</code>，并在 <code>SKILL.md</code> 里说明什么时候读取。</li><li>可重复执行的操作放到 <code>scripts/</code>，不要让 AI 每次重写。</li><li>最终产物需要的模板和素材放到 <code>assets/</code>。</li></ol><p>例如：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 高级功能</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 处理表单字段：读取 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`references/forms.md\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 处理修订痕迹：读取 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`references/redlining.md\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 需要批量转换：运行 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`scripts/convert_batch.py\`</span></span></code></pre></div><p>这样 AI 不需要每次加载所有资料，只在任务需要时读取对应文件。</p><h2 id="第-8-步-让-skill-creator-验证-skill" tabindex="-1">第 8 步：让 skill-creator 验证 Skill <a class="header-anchor" href="#第-8-步-让-skill-creator-验证-skill" aria-label="Permalink to &quot;第 8 步：让 skill-creator 验证 Skill&quot;">​</a></h2><p>Skill 写完后，不要只靠感觉判断。</p><p>你可以继续让 Codex 使用 <code>skill-creator</code> 做验证：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用 skill-creator 检查这个 skill 是否合格：</span></span>
<span class="line"><span>/Users/xxx/.codex/skills/contract-review</span></span>
<span class="line"><span></span></span>
<span class="line"><span>重点检查：</span></span>
<span class="line"><span>1. description 是否能准确触发。</span></span>
<span class="line"><span>2. SKILL.md 是否太长。</span></span>
<span class="line"><span>3. scripts、references、assets 是否拆分合理。</span></span>
<span class="line"><span>4. 是否存在和其他 skill 冲突的地方。</span></span>
<span class="line"><span>5. 是否缺少真实使用例子。</span></span></code></pre></div><p><code>skill-creator</code> 会从几个角度检查：</p><ul><li><code>SKILL.md</code> 是否存在。</li><li>YAML FrontMatter 是否合法。</li><li><code>name</code> 和 <code>description</code> 是否存在。</li><li>Skill 名称是否符合规则。</li><li>目录结构是否有明显问题。</li><li><code>SKILL.md</code> 是否把太多内容塞进正文。</li><li>资源目录是否真正有必要。</li><li>触发边界是否清楚。</li></ul><p>如果 Skill 里包含脚本，还应该实际运行脚本，确认它能工作。脚本类 Skill 最怕“看起来写了工具，实际跑不通”。</p><h2 id="创建-skill-时最容易犯的错误" tabindex="-1">创建 Skill 时最容易犯的错误 <a class="header-anchor" href="#创建-skill-时最容易犯的错误" aria-label="Permalink to &quot;创建 Skill 时最容易犯的错误&quot;">​</a></h2><h3 id="_1-把-skill-写成大号-system-prompt" tabindex="-1">1. 把 Skill 写成大号 System Prompt <a class="header-anchor" href="#_1-把-skill-写成大号-system-prompt" aria-label="Permalink to &quot;1. 把 Skill 写成大号 System Prompt&quot;">​</a></h3><p>System Prompt 是全局规则，适合放长期不变、每次都要遵守的要求。</p><p>Skill 是按需加载的模块，适合放某类任务的专业流程。</p><p>如果你把所有规则都塞进一个 Skill，最后它就会变成另一个臃肿的 System Prompt。</p><h3 id="_2-description-太宽泛" tabindex="-1">2. description 太宽泛 <a class="header-anchor" href="#_2-description-太宽泛" aria-label="Permalink to &quot;2. description 太宽泛&quot;">​</a></h3><p>触发描述越模糊，越容易误触发。</p><p>比如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;帮助用户写东西&quot;</span></span></code></pre></div><p>这会匹配文章、邮件、代码注释、产品文档、广告文案、小说，几乎没有边界。</p><p>更好的方式是拆成多个 Skill：</p><ul><li>周报整理。</li><li>商业文案写作。</li><li>产品需求文档。</li><li>审校润色。</li></ul><p>每个 Skill 只解决一个稳定场景。</p><h3 id="_3-只写原则-不写流程" tabindex="-1">3. 只写原则，不写流程 <a class="header-anchor" href="#_3-只写原则-不写流程" aria-label="Permalink to &quot;3. 只写原则，不写流程&quot;">​</a></h3><p>“专业”“自然”“高质量”“深入”都不是可执行步骤。</p><p>Skill 里需要把这些词翻译成动作：</p><ul><li>开头先给结论。</li><li>每个判断解释原因。</li><li>涉及工具时给出命令。</li><li>涉及代码时说明运行方式。</li><li>最后写限制和下一步。</li></ul><h3 id="_4-放太多无关文档" tabindex="-1">4. 放太多无关文档 <a class="header-anchor" href="#_4-放太多无关文档" aria-label="Permalink to &quot;4. 放太多无关文档&quot;">​</a></h3><p>Skill 不是给人看的项目文档仓库，而是给 AI 执行任务用的工作包。</p><p>通常不需要额外创建：</p><ul><li><code>README.md</code></li><li><code>INSTALLATION_GUIDE.md</code></li><li><code>QUICK_REFERENCE.md</code></li><li><code>CHANGELOG.md</code></li></ul><p>除非某个文件会被 AI 在执行任务时直接使用，否则不要放进 Skill。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>用 <code>skill-creator</code> 创建 Skill 的重点，不是让 AI 帮你写一个更长的 prompt，而是让它把一类高频任务整理成可触发、可执行、可维护的工作流。</p><p>你提供越具体的使用例子、触发条件、输出要求和资源需求，<code>skill-creator</code> 生成的 Skill 就越稳定。</p><p>一个好 Skill 的第一版不需要完美。先让它在真实任务里跑起来，再根据失败点补规则、补反例、拆资源、加脚本，这才是 Skill 真正变强的过程。</p>`,125)])])}const u=a(e,[["render",p]]);export{k as __pageData,u as default};
